class EventBus:
    """Publish each AgentEvent to current subscribers."""

    def publish(self, event: "AgentEvent") -> None:
        for subscriber in self.subscribers:
            subscriber(event)

class EventStore:
    def append(self, task_id: str, event: "AgentEvent") -> None:
        self.events_by_task.setdefault(task_id, []).append(event)

    def list_by_task(self, task_id: str) -> list["AgentEvent"]:
        return list(self.events_by_task.get(task_id, []))

class TraceService:
    def build_trace(self, task_id: str) -> "TaskTrace":
        """Build an ordered trace from every event belonging to task_id."""
        events = self.event_store.list_by_task(task_id)
        return TaskTrace(task_id=task_id, events=sorted(events, key=lambda item: item.sequence_id))

class DiagnosisService:
    def validate_report(self, report: "DiagnosisReport") -> None:
        """Every finding evidence_ids entry must reference known Evidence."""
        known_ids = {item.evidence_id for item in report.evidence}
        for finding in report.findings:
            if not set(finding.evidence_ids) <= known_ids:
                raise ValueError("DiagnosisReport contains an unknown evidence reference")

